import difflib

def _words(name):
    cleaned = name.lower().replace(".", "").replace(",", "").replace("-", "")
    return [w for w in cleaned.split() if w not in ("ltd", "limited")]

def match_supplier(raw, known):
    words = _words(raw)
    if not words:
        return None
    joined = {" ".join(_words(n)): sid for sid, n in known.items()}
    key = " ".join(words)
    if key in joined:
        return joined[key]
    contains = [sid for sid, n in known.items() if set(words) <= set(_words(n))]
    if len(contains) == 1:
        return contains[0]
    if len(contains) > 1:
        return None
    close = difflib.get_close_matches(key, list(joined), n=2, cutoff=0.9)
    return joined[close[0]] if len(close) == 1 else None

