import math

def reorder_list(stock, cover_days):
    out = []
    for s in stock:
        if s["daily_sales"] <= 0:
            continue
        target = s["daily_sales"] * (s["lead_days"] + cover_days)
        if s["on_hand"] < target:
            out.append((s["product"], math.ceil(target - s["on_hand"])))
    return sorted(out)

