            continue
        days = (today - datetime.date.fromisoformat(sale_date)).days
        if days < 0:
            continue
        key = "0-30" if days <= 30 else "31-60" if days <= 60 else "61-90" if days <= 90 else "over 90"
        out[key] += balance
    return out

