def measure_outcome(before, after, expected_saving):
    observed = before - after
    pct = round(100.0 * observed / expected_saving) if expected_saving > 0 else None
    if observed >= expected_saving and observed > 0:
        verdict = "target met"
    elif observed > 0:
        verdict = "partly met"
    else:
        verdict = "no saving"
    return {"observed_saving": observed, "achieved_pct": pct, "verdict": verdict, "proven_cause": False}

