def upsert(existing, incoming):
    merged = {r["id"]: dict(r) for r in existing}
    latest = {}
    for r in incoming:
        latest[r["id"]] = dict(r)
    inserted = updated = unchanged = 0
    for rid, rec in latest.items():
        if rid not in merged:
            inserted += 1
        elif merged[rid] == rec:
            unchanged += 1
        else:
            updated += 1
        merged[rid] = rec
    return {"rows": [merged[k] for k in sorted(merged)], "inserted": inserted, "updated": updated, "unchanged": unchanged}

