TEXT = ["what", "why", "evidence", "action", "expected_result", "monitoring"]

def build_finding(**fields):
    for name in TEXT:
        value = fields.get(name)
        if not isinstance(value, str) or not value.strip():
            raise ValueError("missing: " + name)
    if fields.get("urgency") not in ("today", "this week", "this month"):
        raise ValueError("bad urgency")
    if fields.get("confidence") not in ("low", "medium", "high"):
        raise ValueError("bad confidence")
    estimated = fields.get("impact_estimated")
    if not isinstance(estimated, (int, float)) or estimated <= 0:
        raise ValueError("bad impact")
    measured = fields.get("impact_measured")
    out = {k: fields[k] for k in TEXT}
    out.update(urgency=fields["urgency"], confidence=fields["confidence"], impact_estimated=estimated,
               impact_measured=measured, status="open" if measured is None else "measured")
    return out

